query FetchProductVariantsMedia($id: ID!) {
      product(id: $id) {
        variants(first: 50) {
          edges {
            node {
              id
              media(first: 10) { edges { node { ... on MediaImage { id } } } }
            }
          }
        }
      }
    }

query FetchProductMedia($id: ID!) {
      product(id: $id) {
        status
        media(first: 50) {
          edges {
            node {
              ... on MediaImage {
                id
                alt
                image { url altText }
              }
            }
          }
        }
      }
    }

mutation AppendVariantMedia($productId: ID!, $variantMedia: [ProductVariantAppendMediaInput!]!) {
        productVariantAppendMedia(productId: $productId, variantMedia: $variantMedia) {
          userErrors { field message }
        }
      }
